import{_ as s,l as i,o as a,c as d,v as o,p as n,x as t,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"挂载与超级块","description":"","frontmatter":{"title":"挂载与超级块","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mount-super.md","filePath":"cs/mount-super.md","lastUpdated":1789023840000}'),u={name:"cs/mount-super.md"};function h(m,e,_,f,E,S){const r=i("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="挂载与超级块" tabindex="-1">挂载与超级块 <a class="header-anchor" href="#挂载与超级块" aria-label="Permalink to &quot;挂载与超级块&quot;">​</a></h1><div class="epigraph"><p>超级块描述一次已挂载的文件系统实例；挂载点把该实例的根接到目录树的某个 dentry 上。</p><footer>—— 据 Kleiman 的 vnode；McKusick 对 BSD 挂载的整理；Linux VFS 文档</footer></div><p><a href="/cs/vfs">上一课</a>给出操作表，底下可以是不同 FS。<a href="/cs/path-lookup">路径查找</a>会碰到「换超级块」的接口。<a href="/cs/inode-dir">inode</a> 号只在一台已挂载实例内有意义。缺口是<strong>挂载</strong>：设备、类型、根 inode、选项，以及用户看见的单棵树如何由多棵拼成。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若全局只有一棵磁盘上的树，U 盘与 NFS 无法接到 <code>/mnt</code>。若每个 FS 自己实现整条 <code>open</code> 路径，VFS 白做。缺口：<code>mount</code> 读设备上的超级块（魔数、块大小、根 inode），在内核创建 <code>super_block</code>，把某目录变成挂载点——lookup 走到该 dentry 时切换 super，从客 FS 的根继续。卸载要保证无忙 inode，并写回脏元数据。</p><p>本课不把绑定挂载与命名空间的容器语义写完，那是隔离课。</p><p><span class="marginnote">同一设备可只读挂、可挂多次（实现相关）。proc、sysfs 没有块设备，超级块仍存在，只是内存里造出来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>mount(source, target, fstype, flags, data)</code>：VFS 调该类型的 <code>fill_super</code>，建立根 dentry。后续 <a href="/cs/dcache">dcache</a> 在挂载点上有「越过」逻辑。<code>umount</code> 检查引用。根文件系统在启动时由 init 指定，后课 early-boot 再接。用户路径仍从进程 root 开始，不感知设备号。</p>',9)),(a(),n(p,null,{default:t(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E8%AE%BE%E5%A4%87%E6%88%96%E4%BC%AA%20FS%22%5D%20--%3E%20SB%5B%22super_block%22%5D%0A%20%20SB%20--%3E%20ROOT%5B%22%E8%AF%A5%E5%AE%9E%E4%BE%8B%E7%9A%84%E6%A0%B9%20dentry%22%5D%0A%20%20MNT%5B%22%E6%8C%82%E8%BD%BD%E7%82%B9%22%5D%20--%3E%20ROOT%0A%20%20LOOK%5B%22lookup%20%E9%81%87%E6%8C%82%E8%BD%BD%E7%82%B9%22%5D%20--%3E%20SB%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>超级块把「哪一种 FS、哪一份数据」变成内核对象，VFS 操作表有了 <code>this</code> 指针。崩溃一致性后课要写回的正是这份 super 与其 inode。不要把挂载写成包管理器或容器镜像教程；对象只是树的拼接。块如何进内存，缓冲课已经在下一课等着。</p><p>与<a href="/cs/user-kernel-split">用户/内核分裂</a>无关：挂载是命名空间里的树，不是虚地址。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 loop 设备加密的全部栈。不保证所有 FS 支持在线 resize。下一课缓冲与脏页会假定：已有一块已挂载实例，读写落到块号。</p><p>后课默认：目录树可由多个 super 拼成。块在内存中的 Cache 与脏位，下一课缓冲与脏页。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>super_block 是一次挂载实例；挂载点切换查找。</li><li>伪文件系统同样有超级块，只是无磁盘。</li><li>脏缓冲与写回是下一课。</li><li>出处：Kleiman, 1986；McKusick et al., <em>4.4BSD</em>；Linux VFS。</li></ul>',8))])}const k=s(u,[["render",h]]);export{A as __pageData,k as default};
